using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using StockManagement.Data;using StockManagement.Models;using StockManagement.Services;
namespace StockManagement.Controllers;[Authorize(Roles=Roles.Admin+","+Roles.Manager+","+Roles.Staff)] public class SuppliersController:Controller{readonly ApplicationDbContext _db;readonly AuditService _audit;public SuppliersController(ApplicationDbContext db,AuditService audit){_db=db;_audit=audit;}public IActionResult Index(string? search){var q=_db.Suppliers.AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Name.Contains(search)||x.Email.Contains(search)||x.Phone.Contains(search));ViewBag.Search=search;return View(q.OrderBy(x=>x.Name).ToList());}public IActionResult Create()=>View(new Supplier());[HttpPost,ValidateAntiForgeryToken]public IActionResult Create(Supplier s){if(!ModelState.IsValid)return View(s);_db.Suppliers.Add(s);_db.SaveChanges();_audit.Add("Supplier","Create",$"Created {s.Name}",User.Identity?.Name??"System");return RedirectToAction(nameof(Index));}public IActionResult Edit(int id){var s=_db.Suppliers.Find(id);return s==null?NotFound():View(s);}[HttpPost,ValidateAntiForgeryToken]public IActionResult Edit(Supplier s){if(!ModelState.IsValid)return View(s);var e=_db.Suppliers.Find(s.Id);if(e==null)return NotFound();e.Name=s.Name;e.Email=s.Email;e.Phone=s.Phone;e.Address=s.Address;e.IsActive=s.IsActive;_db.SaveChanges();return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public IActionResult Delete(int id){var s=_db.Suppliers.Find(id);if(s!=null){_db.Suppliers.Remove(s);try{_db.SaveChanges();}catch{TempData["Error"]="Supplier is referenced by a purchase.";}}return RedirectToAction(nameof(Index));}}
